using UnityEngine;
using UnityEditor;
using UnityEngine.AI;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            result.Log("UTC=" + System.DateTime.UtcNow.ToString("o"));
            var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
            result.Log("scene=" + scene.path + " dirty=" + scene.isDirty + " play=" + EditorApplication.isPlaying + " compileFailed=" + EditorUtility.scriptCompilationFailed);
            foreach (var root in scene.GetRootGameObjects())
            {
                result.Log("ROOT " + root.name);
                foreach (var c in root.GetComponentsInChildren<Component>(true))
                    if (c && (c.GetType().Name.Contains("NavMesh") || c.GetType().Name == "SessionFlow"))
                        result.Log("COMPONENT " + c.GetType().FullName + " " + c.name);
            }

            for (int i = 0; i < NavMesh.GetSettingsCount(); i++)
            {
                var s = NavMesh.GetSettingsByIndex(i);
                result.Log("AGENT " + s.agentTypeID + " radius=" + s.agentRadius + " height=" + s.agentHeight);
            }

            result.Log("navData=" + AssetDatabase.FindAssets("t:NavMeshData", new[]{"Assets"}).Length + " vertices=" + NavMesh.CalculateTriangulation().vertices.Length);
            for (int i = 0; i < 32; i++)
                if (!string.IsNullOrEmpty(LayerMask.LayerToName(i)))
                    result.Log("LAYER " + i + " " + LayerMask.LayerToName(i));
            foreach (var guid in AssetDatabase.FindAssets("t:AnimationClip", new[]{"Assets"}))
            {
                var p = AssetDatabase.GUIDToAssetPath(guid);
                result.Log("ANIMATION_ASSET " + p);
            }

            foreach (var guid in AssetDatabase.FindAssets("t:Model", new[]{"Assets"}))
            {
                var p = AssetDatabase.GUIDToAssetPath(guid);
                if (!p.Contains("/Character/"))
                    continue;
                var go = AssetDatabase.LoadAssetAtPath<GameObject>(p);
                var a = go.GetComponent<Animator>();
                result.Log("CHARACTER " + p + " avatar=" + (a && a.avatar ? a.avatar.isValid + "/" + a.avatar.isHuman : "none") + " scale=" + go.transform.localScale);
                foreach (var r in go.GetComponentsInChildren<Renderer>(true))
                    foreach (var m in r.sharedMaterials)
                        result.Log("MATERIAL " + m.name + " shader=" + m.shader.name);
            }

            result.Log("PIPELINE " + UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline);
        }
    }
}
